        "std::optional<PeriodicCoverCoalescer::Cover> PeriodicCoverCoalescer::coalesce(const std::vector<Arc>& xs,long long p){if(p<=0)return std::nullopt;std::vector<std::pair<long long,int>> ev;for(auto a:xs){if(a.begin<0||a.begin>=p||a.end<0||a.end>=p)return std::nullopt;if(a.begin==a.end)continue;if(a.begin<a.end){ev.push_back({a.begin,1});ev.push_back({a.end,-1});}else{ev.push_back({0,1});ev.push_back({a.end,-1});ev.push_back({a.begin,1});ev.push_back({p,-1});}}std::sort(ev.begin(),ev.end());std::vector<Arc> out;int depth=0;long long start=0;for(size_t i=0;i<ev.size();){long long x=ev[i].first,before=depth;while(i<ev.size()&&ev[i].first==x){depth+=ev[i].second;++i;}if(before==0&&depth>0)start=x;if(before>0&&depth==0)out.push_back({start,x});}if(out.size()==1&&out[0].begin==0&&out[0].end==p)return Cover{true,{}};if(out.size()>1&&out.front().begin==0&&out.back().end==p){Arc wrap{out.back().begin,out.front().end};out.erase(out.begin());out.back()=wrap;}return Cover{false,out};}",
