        "std::optional<std::vector<CyclicRangeSubtractor::Arc>> CyclicRangeSubtractor::subtract(Arc src,const std::vector<Arc>& cuts,long long p){if(p<=0||src.begin<0||src.begin>=p||src.end<0||src.end>=p||src.begin==src.end)return std::nullopt;auto linear=[p](Arc a){std::vector<std::pair<long long,long long>> v;if(a.begin<a.end)v.push_back({a.begin,a.end});else{v.push_back({a.begin,p});v.push_back({0,a.end});}return v;};std::vector<std::pair<long long,long long>> remain=linear(src);for(auto c:cuts){if(c.begin<0||c.begin>=p||c.end<0||c.end>=p)return std::nullopt;for(auto cut:linear(c)){std::vector<std::pair<long long,long long>> next;for(auto s:remain){if(cut.second<=s.first||cut.first>=s.second)next.push_back(s);else{if(s.first<cut.first)next.push_back({s.first,cut.first});if(cut.second<s.second)next.push_back({cut.second,s.second});}}remain=next;}}std::vector<Arc> out;for(auto s:remain)out.push_back({s.first,s.second==p?0:s.second});std::stable_sort(out.begin(),out.end(),[=](Arc a,Arc b){return forward_distance(src.begin,a.begin,p)<forward_distance(src.begin,b.begin,p);});return out;}",
